\label{o.c}
We say that $\sigma$ verifies the \emph{optimality condition} (in short OC) if, for every $w\in \{0,1\}^\omega$, there exists a sequence of integers $(h_i)_{i\in\mathbb{N}}\in \{1,2,\dots,2^k\}^\mathbb{N}$ such that 
\begin{equation}
w=\prod_{i=1}^\infty v_{(h_i)}
\label{OC1}
\end{equation}

\label{defialter}
We say that the $k$-block substitution $\sigma$ is \textit{alternating} if there exist $k$ simple substitutions $\sigma_1,\sigma_2,\dots \sigma_k$ such that the map $\sigma_e$ defined below is an extension of $\sigma$ on $\{0,1\}^\infty$: 
\begin{equation}
\sigma_e(u)=\prod_{j=0}^{n-1} \left(\prod_{i=1}^k \sigma_i(u_{i+jk})\right)\prod_{i=1}^m \sigma_i(u_{i+nk})
\label{alternating}
\end{equation}
where $|u|=nk+m$ ($n,m\in\mathbb{N}_0$, $m<k$) and the first (last) product has to be taken as empty if $n=0$ ($m=0$).

A $k$-block substitution $\sigma$ is said to be:
\begin{enumerate}
\item  \emph{Strongly erasing} if for every $w \in \lbrace0,1\rbrace^*$ there is $n \in \mathbb{N}$ such that:
\begin{equation}
 \epsilon\in w^{[n]} 
\label{str_eras}
\end{equation} 

\noindent So, when $\sigma$ is strongly erasing, for every $w\in\{0,1\}^*$ there exist a positive integer $n$ and finite words $r_{(0)},\ldots, r_{(n-1)}$, which we call \textit{erasing $k$-roundings of $w$}, such that: i) $r_{(0)}$ is a $k$-rounding of $w$;
ii) for any integer $j$ such that $1 \le j\le n-1$,  $r_{(j)}$ is a $k$-rounding of $\sigma(r_{(j-1)})$; iii) $\sigma(r_{(n-1)})=\epsilon $.
The $k$-extensions corresponding to the $n$ $k$-roundings just defined, i.e. the $n$ words $\{e_{(i)}\}_{i=0,\ldots, n-1}$, each belonging to $\{0,1\}^{< k}$, such that $we_{(0)}=r_{(0)}$ and, for $1\le i\le n-1$, $\sigma(r_{(i-1)})e_{(i)}=r_{(i)}$, will be called \textit{erasing $k$-extensions} for $w$. Notice that there can be more than one set of erasing $k$-roundings and of erasing $k$-extensions for a given word.

\item \emph{Completely erasing} if it is alternating (in the sense of Definition \ref{defialter}) and, for every $w\in\{0,1\}^*$, there is $n \in \mathbb{N}$ such that:
\begin{equation}
\sigma^n(w)=\epsilon
\label{com_eras}
\end{equation}
\noindent The smallest positive integer $n$ verifying Eq.\eqref{com_eras}, indicated by $\epsilon(w)$, is called \emph{vanishing order} of $w$.

\item \emph{Boundedly erasing} if $\sigma$ is completely erasing and $\epsilon(\cdot)$ is bounded over $\{0,1\}^*$.
\end{enumerate}

For every $k$-block substitution $\sigma$, we have:
\begin{equation*}
\text{boundedly erasing}\implies \text{completely erasing} \implies \text{strongly erasing} \implies \text{erasing}
\end{equation*}
\label{classes}

Take $x\in \mathcal{C}^\sigma$ and fix $n\in \mathbb{N}$ . Then $\widetilde{x}=\prod_{h=1}^\infty w_{(i_h)}$ ($i_h\in \lbrace1,\ldots2^kbrace$) and $\widetilde{x}$ does not have $w_\epsilon^\infty$ as a $k$-factor.  Since $|v_{(j)}|\ge 1$ if $w_{(j)}
e w_\epsilon$, there is a prefix $p$ of $\widetilde{x}$ such that $\left| p ight|=m k$ ($m\in \mathbb{N}$) and $\left| \sigma(p)ight| \ge n$. Since $x$ has a unique binary expansion, for every $y\in\mathbb{I}$ such that $\left|x-y ight|<2^{-mk}$, we have that $\widetilde{x},\widetilde{y}$ coincide at least up to the first $mk$ digits. Then
$\left| f_\sigma(x) - f_\sigma(y)ight|\le 2^{-(\left|\sigma(p)ight|)}\le 2^{-n}$. Since we assume $w_{\epsilon} 
eq 1^k$,  recalling that $\sigma$ acts on the 1-periodic expansion of dyadic rationals, the argument above shows that $f_\sigma$ is left continuous on $\mathbb{Q}_2\setminus\{0\}$ (notice that, assuming instead $w_{\epsilon} 
e 0^k$, we would get right continuity on $\mathbb{Q}_2\setminus \{1\}$). 


oindent Finally, interval maps with countably many discontinuities are pointwise limit of continuous functions, that is Baire-1 (see for instance \cite{van1982second}).

Let $\Xi\subset \mathbb{N}_0^{\mathbb{N}}$ be an uncountable set of sequences such that
\begin{equation}
a,b\in\Xi, a\ne b\implies \forall M>0,\ \exists n\in\mathbb{N}_0: n>M\ \text{and}\ a_n\ne b_n
\label{defiXi}
\end{equation}
Set $\Omega=\Xi\cap \{0,1\}^{\mathbb{N}}$ and call  $\Xi^+$ $(\Omega^+)$ the uncountable subset of $\Xi$ ($\Omega$) such that no one of its elements is ultimately 0. 
\label{defiomegaxi}

Take $y\in\mathbb{I}\setminus \{0\}$ and write $\widetilde{y}=\prod_{i=1}^\infty w_{(h_i)}$. Let $(h_{i_j})_{j\in \mathbb{N}}$ be the subsequence of all $h_i$ such that $w_{(h_{i_j})}\ne w_\epsilon$. Then we define:
\begin{equation}
y^\circ= \xi\in\mathbb{I}\ \text{such that}\  \widetilde{\xi}=\prod_{i=1}^\infty u_{(j)},  \text{where } u_{(j)}=w_{(h_{i_j})}
\end{equation}
\label{circ}

\noindent For $u\in\{0,1\}^\omega$ such that $u=\prod_{i=1}^\infty u_{(i)}$ (with $u_{(i)}\in\{0,1\}^k$), and for every $a\in\Xi$, we set:
\begin{equation}
\xi_{u}(a)=0.\prod_{i=1}^{\infty}w_\epsilon^{a_i}u_{(i)}
\label{mapxi}
\end{equation}
\label{xxi}

Suppose that $\sigma$ verifies the optimality condition \ref{o.c} and that, for the point $y\in\mathbb{I}$, the words $w\in\{0,1\}^\omega$ verifying $y=0.w$ are such that the sequence $h_1,h_2\dots$ satisfying Eq.\eqref{OC1}, and  such that $v_{(h_i)}\ne\epsilon$ for every $i\in\mathbb{N}$, is unique.
If $x$ is a limit point of $f_\sigma^{-1}(y)$, then one of the following cases occurs: 
\begin{enumerate}
\item $x\in f_\sigma^{-1}(y)$
\item $x=0.vw_{\epsilon}^\infty$, with $|v|=nk$ for some non-negative integer $n$.
\item $y\in\mathcal{F}^\sigma$ and $x=0.a\prod_{i=1}^\infty 0^{n_i}w_\epsilon^{m_i}$, 
where $a\in\{0,1\}^*$, $\{m_i\}$ is a sequence of non-negative integers which is ultimately zero and $n_i$ are positive integers such that $|a|+\sum_{j=1}^{i}n_j$ is a multiple of $k$ for every $i\in\mathbb{N}$.
\end{enumerate} 
\label{limit_}

\noindent We divide the proof in four cases.
\begin{enumerate}
\item $y\notin \mathcal{Q}_2\cup\mathcal{F}^\sigma$. 

\noindent Then $y$ has a unique binary expansion $u$ and, by hypothesis, there exists a unique sequence $h_1, h_2,\dots$ such that  $u=\prod_{i=1}^\infty v_{(h_i)}$. We can assume $v_{(h_i)} \ne\epsilon$ for every $i\in\mathbb{N}$. Moreover, since $y\notin \mathcal{F}^\sigma$, $w=\prod_{i=1}^\infty w_{(h_i)}$ does not end in $0^\infty$. Therefore, the point $x=0.w$ belongs to $f_\sigma^{-1}(y)$ and it coincides with $x^\circ$. By uniqueness of the sequence $h_1, h_2\dots$, it follows that $f_\sigma^{-1}(y)$ can be written as

\begin{equation}
\bigcup_{a\in {\mathbb{N}_0}^{\mathbb{N}}} \xi_{\widetilde{x^\circ}} (a)
\end{equation}
where $\xi_{\widetilde{x^\circ}}:{\mathbb{N}_0}^{\mathbb{N}}\to \mathbb{I}$ is the map defined in \ref{xxi}. 
If $z$ is a limit point of $f_\sigma^{-1}(y)$, there exists a sequence $\lbrace a^{(n)} \rbrace_{n\ge1}$  of elements of ${\mathbb{N}_0}^{\mathbb{N}}$ such that $\xi_{\widetilde{x^\circ}}(a^{(n)})\xrightarrow[n \to \infty]{} z$. Notice that, since $\widetilde{x^\circ}$ does not end with $0^\infty$, neither does $\widetilde{\xi_{\widetilde{x^\circ}}}(a)$ for every $a\in\mathbb{N}_0^\mathbb{N}$. 

\noindent We indicate by $ a_{i}^{(n)}$ the $i$-th element of the sequence $ a^{(n)}$.  Let us first prove that, for every $i\in\mathbb{N}$, there exists $a_i=\lim_{n\to\infty} a_i^{(n)}\le\infty$. Indeed, suppose that $m$ is the smallest positive integer such that $a_m^{(n)}$ admits two distinct sublimits, i.e. such that there exist two subsequences $n_h$ and $n_j$ such that $a_m^{(n_h)}\to\overline{a_m}$ and $a_m^{(n_j)}\to\overline{\overline{a_m}}$. Set
$q=w_\epsilon^{a_1}w_{(h_1)}\dots w_\epsilon^{a_{m-1}}w_{(h_{m-1})} w_\epsilon^{\min\{\overline{a_i},\overline{\overline{a_i}}\}}$ and $\delta=|\overline{a_i}-\overline{\overline{a_i}}|$. Then the points 
\begin{equation}
\{\xi_{\widetilde{x^\circ}}(a^{(n_h)})\}_{h\in\mathbb{N}},\ \{\xi_{\widetilde{x^\circ}}(a^{(n_j)})\}_{j\in\mathbb{N}}
\label{points_}
\end{equation}
ultimately belong respectively to the (closed) intervals $[qw_\epsilon^\delta w_{(h_m)}]$ and $[qw_{(h_m)}]$, which, recalling that $w_\epsilon\ne w_{h_m}$, have nonempty intersection only if either 1) $\delta=0$ or 2) $\delta\in\mathbb{N}$ and $w_{(h_m)}=p0$ and $w_\epsilon=p1$, or alternatively $w_{(h_m)}=p1$ and $w_\epsilon=p0$ for some $p\in\{0,1\}^{k-1}$. We can assume the former (in the other case the reasoning is completely analogous). A point $z$ in $[qw_\epsilon^\delta w_{(h_m)}]\cap [qw_{(h_m)}]$ must then admit the two binary forms $z=0.qp10^\infty$ and $z=0.qp01^\infty$. The first one can be only achieved if $\delta=1$, $w_{(h_m)}=0^k$ and $w_{(h_j)}=w_{(h_m)}$ for all $j>m$. This in turn implies that the second binary form, ending in $1^\infty$, can be only obtained if $w_\epsilon=1^k$.  But then $w_{(h_m)}$ and $w_\epsilon$ differ on every digit, which contradicts the existence of the word $p$ required before. It follows that it has to be $\delta=0$, which implies $\overline{a_i}=\overline{\overline{a_i}}$.

\noindent Assume now that it is nonempty the set $A$ of $i\in \mathbb{N}$ such that $a_i=\infty$, and set $z=0.u$. 
Then 
\begin{equation}
u=pw^\infty_{\epsilon},
\label{limitpoint}
\end{equation}
where $p\in \lbrace0,1\rbrace^*$ is the word $p=w_{\epsilon}^{a_1}w_{(h_1)}w_{\epsilon}^{a_2}w_{(h_2)}\ldots w_{\epsilon}^{a_{\bar{i}-1}}w_{(h_{\bar{i}-1})}$
with $\bar{i}=\min A$. Therefore, it falls under point 2. in the statement of the Lemma.

\noindent Suppose instead that $\lim_{n\to\infty} a^{(n)}_i\ne\infty$ for every integer positive $i$. Then $u=\prod_{i=1}^\infty w_{\epsilon}^{a_i}w_{(h_i)}$, which implies that $z\in f_\sigma^{-1}(y)$. Therefore, it falls under point 1. in the statement of the Lemma. Notice also that in this case, since $u$ is obtained from $\widetilde{x}$ by inserting (infinitely many times) finite concatenations of $w_\epsilon$ with itself in a word not having $w_\epsilon$ as a $k$-factor, $u$ cannot end in $0^\infty$ either if $w_\epsilon=0^k$ or if not, so that $u=\widetilde{z}$.

\item $y\in \mathcal{Q}_2\setminus\mathcal{F}^\sigma$.

\noindent By hypothesis $y$ has two binary expansions, $\widetilde{y}$ and $u\in\{0,1\}^\omega$ such that $u=v0^\infty$.

Then: i) by assumption there exist two words $w^{(1)},w^{(2)}\in\{0,1\}^\omega$ not having $w_\epsilon$ as a $k$-factor, such that $\sigma(w^{(1)})=\widetilde{y}$ and $\sigma(w^{(2)})=u$; ii) there is a countable family of finite integer sequences $$J=\cup_{j\in\mathbb{N}_0} \{j_i\}_{i=1\dots m_j}$$ such that there are words $w^{(3)}_{(j)}=\prod_{i=1}^{m_j} w_{(j_i)}$ ($m_j\in\mathbb{N}$) having the property that $\sigma\left(w^{(3)}_{(j)}\right)=v0^{g_j}$ for suitable non-negative integers $g_0,g_1,\dots\in \mathbb{N}_0$. Notice that the family $J$ is infinite, because the optimality condition ensures that there are arbitrarily large integers $h$ such that we can write $v0^h$ as a concatenation of the words $v_{(i)}=\sigma(w_{(i)})$. Recalling the definition of $f_\sigma$ (Eq. \eqref{fsigma__}), it follows that any point of type $0.w^{(3)}_{(j)}$ belongs to $f_\sigma^{-1}(y)$.

Then the set $f_\sigma^{-1}(y)$ decomposes as $S_1\cup S_2 \cup S_3$, where 
\begin{eqnarray*}\label{fibercase2}
&S_1=\bigcup_{a\in {\mathbb{N}_0}^{\mathbb{N}}} \xi_{w^{(1)}} (a)\ \ ,\ \ S_2=\bigcup_{a\in {\mathbb{N}_0}^{\mathbb{N}}} \xi_{w^{(2)}} (a)\\
&\\
&S_3= \bigcup_{a\in \mathbb{N}_0^{m}, j\in\mathbb{N}_0} \{x\in \mathbb{I} : x=0.\left(\prod_{i=1}^{m_j}w_\epsilon^{a_i}w_{(j_i)}\right)w_\epsilon^\infty\},
\end{eqnarray*}

where $\xi_{w^{(i)}}$ ($i=1,2$) is the map defined in \ref{xxi}. Since a limit point of a finite union of sets is limit point of (at least) one of the sets, we can repeat the argument used in Case 1. separately for $S_1$ and $S_2$. A similar argument shows that also the set $S_3$ has always limit points of the form \eqref{limitpoint}.

\item $y\in \mathcal{F}^\sigma\setminus \mathcal{Q}_2$.

\noindent Then there is no $x\in\mathbb{I}$ such that $f_\sigma(x)=y$ and $\widetilde{x}$ does not have $w_\epsilon$ as a $k$-factor. Indeed, by definition of $\mathcal{F}^\sigma$, there is $a\in\{0,1\}^*$ such that $0.\sigma(a0^\infty)=y$. Recalling that $f_\sigma$ is defined by the action of $\sigma$ on the 1-periodic expansion of dyadic rationals, it follows that 
\begin{equation}x\in f^{-1}_\sigma(y)\implies x=0.a\prod_{i=1}^\infty 0^{n_i}w_\epsilon^{m_i}
\label{0a}
\end{equation}
where $\{m_i\}$ is a sequence of non-negative integers which is not ultimately zero and $n_i$ are positive integers such that $|a|+\sum_{j=1}^{i}n_j$ is a multiple of $k$ for every $i\in\mathbb{N}$.
Let us define the set $\mathcal{B}$ as:
\begin{equation}
\mathcal{B}=\{b\in\{0,1\}^*: b=a\prod_{i=1}^N 0^{n_i}w_\epsilon^{m_i}\ \text{for some $N\in\mathbb{N}_0$}.\}
\label{b_}
\end{equation}  
Recalling Case 1., it follows that the set  
\begin{equation}
\mathcal{B}^\sigma_1=\{0.bw_\epsilon^{\infty} ,\  b\in\mathcal{B}\}
\end{equation}

belongs to $\overline{f_\sigma^{-1}(y)}$,  and its points fall under point 2. in the statement of the Lemma.  Moreover,  it follows that the set
\begin{equation}
\mathcal{B}^\sigma_2=\{0.b0^{\infty} ,\  b\in\mathcal{B}\}
\end{equation}
belongs to $\overline{f_\sigma^{-1}(y)}$,  and its points fall under point 3. in the statement of the Lemma. 

\item $y\in \mathcal{Q}_2\cap\mathcal{F}^\sigma$.

Suppose first that $w_\epsilon\ne 0^k$. By assumption $y$ has two infinite binary expansions, $\widetilde{y}$ and $u\in\{0,1\}^\omega$ such that $u=v0^\infty$ for some finite word $v$. 

Since $y\in \mathcal{F}^\sigma$ and is a dyadic rational, we have that $\sigma(0^k)=0^{N_1}$ or $\sigma(0^k)=1^{N_2}$ for some $N_1,N_2 \in \mathbb{N}$. In the following we consider the first case, a similar argument applies in the other one switching the roles of $\widetilde{y}$ and $u$.  

\noindent Then: i) there exists a word  $w^{(1)} \in \{0,1\}^\omega$ not having $w_\epsilon$ as a $k$-factor, such that $\sigma(w^{(1)}) = \widetilde{y}$; ii) moreover, recalling that $f_\sigma$ is defined by the action of $\sigma$ on the 1-periodic expansion of dyadic rationals and that $\sigma(0^k)$ is a string of 0s, there is no $x\in\mathbb{I}$ such that $\sigma(\widetilde{x})=u$ and $\widetilde{x}$ does not have $w_\epsilon$ as a $k$-factor, while, by definition of $\mathcal{F}^\sigma$, there is $c\in\{0,1\}^*$ such that $\sigma(c0^\infty)=u=v0^\infty$; iii) finally, there is a countable family of finite integer sequences $J=\cup_{j\in\mathbb{N}_0} \{j_i\}_{i=1\dots m_j}$ such that there are words $w^{(2)}_{(j)}=\prod_{i=1}^{m_j} w_{(j_i)}$ ($m_j\in\mathbb{N}$) having the property that $\sigma\left(w^{(2)}_{(j)}\right)=v0^{g_j}$ for suitable non-negative integers $g_j\in \mathbb{N}_0$.  It follows that $f_\sigma^{-1}(y)$ decomposes as $S_1 \cup S_2 \cup S_3$, where
\begin{eqnarray*}
&S_1=\bigcup_{a\in {\mathbb{N}_0}^{\mathbb{N}}} \xi_{w^{(1)}} (a)\ \ ,\ \ S_2=\{x\in \mathbb{I} : x=0.c\prod_{i=1}^\infty 0^{n_i}w_\epsilon^{m_i}\} \\
 &\\
  &S_3= \bigcup_{a\in \mathbb{N}_0^{m},j\in \mathbb{N}_0} \{x\in \mathbb{I} : x=0.\left(\prod_{i=1}^{m_j}w_\epsilon^{a_i}w_{(j_i)}\right)w_\epsilon^\infty\},
\label{fibercase4}
\end{eqnarray*}
where $\{m_i\}$ and $\{n_i\}$ have the same properties of Case 3. and $\xi_{w^{(1)}}$ is the map defined in \ref{xxi}.  Then we can repeat the argument of Case 2. for $S_1$ and $S_3$ and the argument of Case 3. for $S_2$. 

Finally, notice that, if $w_\epsilon=0^k$, the sets $S_2$ and $S_3$ do not belong to $f_\sigma^{-1}(y)$, since $\sigma$ acts on the 1-periodic expansion of dyadic rationals. 
\end{enumerate}

Since $\sigma$ is boundedly erasing, there exists $n=\max_{w\in\{0,1\}^*}\epsilon(w)$ (as $\epsilon(\cdot)\ge 0$ is integer and bounded by assumption). Then, for every $u\in\{0,1\}^\omega$ and for every $m>0$, $\sigma^n(u_1\dots u_m)=\epsilon$, whence, by induction on $m$, we have 
\begin{equation}
\forall u\in\{0,1\}^\omega,\ \ \sigma^n(u)=\epsilon.
\label{boundedd}
\end{equation} 
Take $w^{(0)}\in\{0,1\}^{\omega}$. Suppose by absurde that $\sigma$ verifies the optimality condition. Then there exists $w^{(1)}\in\{0,1\}^\omega$ such that $\sigma(w^{(1)})=w^{(0)}$. Iterating the argument, it  follows that we can construct a sequence of nonempty infinite words $\{w^{(m)}\}_{m\in\mathbb{N}}$ such that, for every $m\in\mathbb{N}$, $\sigma(w^{(m)})=w^{(m-1)}$. But then the word $w^{(N)}$ contradicts \eqref{boundedd} for $N$ large enough. Take now $x\in\mathbb{I}$ such that its $f_\sigma$-orbit is does not contain dyadic rationals other than 0 and 1. Suppose that $f_\sigma^j(x)\ne 0$ for every $j\in\{1,\dots,n-1\}$. Then $\sigma^{n-1}(\widetilde{x})=w_{\epsilon}^{\infty}$ which implies $f_\sigma^{n}(x)=0$. Recalling that 0 is a fixed point of $f_\sigma$ by definition, we have our thesis.

\label{lem_strongly}
If $\sigma$ is strongly erasing and verifies the optimality condition \ref{o.c}, then, for every $w\in\{0,1\}^*$, $u\in\{0,1\}^\infty$, there is a positive integer $h$ depending only on $w$ and a word $v\in\{0,1\}^\infty$, such that: 
\begin{itemize}
\item [a)] $\sigma^h(wv)$ has $u$ as a prefix (in particular it coincides with $u$ if $|u|=\infty$);
\item [b)] for every finite integer sequence $\{n_0,\dots,n_{h-1}\}\in (\mathbb{N}_0)^{h}$, the word $\sigma_w^{i}(v)$ has $e_{(i)}w_\epsilon^{n_i}$ as a prefix for $i\in\{0,\dots,h-1\}$, where $\{e_{(i)}\}_{i=0,\dots,h-1}$ is a set of erasing $k$-extensions of $w$.

\noindent Moreover:
\item [c)] if $\sigma$ is completely erasing, we have the same results and we can choose $h=\epsilon(w)$.
\end{itemize}

Let us indicate by $\{w^{(n)}\}_{n\in\mathbb{N}_0}$ an enumeration of all finite binary words. We will construct inductively a point $x=0.\widetilde{x}$ with the property that there exists a sequence of integers $\{h_n\}_{n\in \mathbb{N}_0}$ such that  $\sigma^{h_n}(\widetilde{x})$ has $w^{(n)}$ as a prefix for every $n$.  

\noindent By Lemma \ref{lem_strongly}, there exists $u^{(1)}\in\{0,1\}^+$ and $h_1\in\mathbb{N}$ such that $\sigma^{h_1}(w^{(0)}u^{(1)})$ has $w^{(1)}$ as a prefix.  Let $\{e_{(j)}^{(0)}\}_{j\in\{0,\dots,h_{1}-1\}}$ be the erasing $k$-extensions of $w^{(0)}$. By Lemma \ref{lem_strongly}, for $\{n^1_0,\dots,n^1_{h_1-1}\}\in (\mathbb{N}_0)^h$, we can select $u^{(1)}$ so that the word $\sigma_{w^{(0)}}^j\left(u^{(1)}\right)$ has $e_{(j)}^{(0)}w_\epsilon^{n_j^1}$ as a prefix for $j\in\{0,\dots,h_1-1\}$. 


\noindent Set $p^{(1)}=w^{(0)}u^{(1)}$. Suppose that we arrived at the step $i-1$ and we have defined $p^{(i-1)}=w^{(0)}u^{(1)}\dots u^{(i-1)}$. At the $i$-th step we have that, again by Lemma \ref{lem_strongly}, there exists $u^{(i)}\in \{0,1\}^+$ and $h_i\in\mathbb{N}$ such that $\sigma^{h_i}(p^{(i-1)}u^{(i)})$ has $w^{(i)}$ as a prefix. Let $\{e_{(j)}^{(i-1)}\}_{i\in\{0,\dots,h_{1}-1\}}$ be the erasing $k$-extensions of $w^{(i-1)}$. By Lemma \ref{lem_strongly}, for $\{n^i_0,\dots,n^i_{h_i-1}\}\in (\mathbb{N}_0)^h$, we can select $u^{(i)}$ so that the word $\sigma_{p^{(i)}}^j\left(u^{(i)}\right)$ has $e_{(j)}^{(i-1)}w_\epsilon^{n^i_j}$ as a prefix for $j\in\{0,\dots,h_i-1\}$. 
By the construction made in Lemma \ref{lem_strongly}, we have $\sigma^{h_i}(p^{(i)})=\epsilon$, and since $p^{(i-1)}$ is always a prefix of $p^{(i)}$, it follows that $h_i\ge h_{i-1}$ for every $i$. We can then define the word $v$ as 
\begin{equation}
v=w^{(0)}\prod_{j=1}^\infty u^{(j)}
\label{d_orbit}
\end{equation} 
so that by construction the $\sigma$-orbit of $v$ has $w^{(n)}$ as a prefix for every $n\in\mathbb{N}_0$. Notice further that different choices for $n_0^i$ ($i\in\mathbb{N}$) produce different words in Eq.\eqref{d_orbit}, which proves that we have uncountably many choices for $v$. If, for every $j\in\mathbb{N}_0$, we take the sequence $(n_j^i)_{i\in\mathbb{N}}$ in the set $\Xi^+$, we are ensured that $\sigma^j(v)$ will not end in $0^\infty$ for every $j$ (either in case $w_\epsilon=0^k$ or not). Therefore, the point $x=0.v=0.\widetilde{x}$ has a dense $f_\sigma$-orbit and the set $\mathcal{D}$ of points with a dense $f_\sigma$-orbit is uncountable.
Finally, by the arbitrariness of the prefix $w^{(0)}$, the set $\mathcal{D}$ is dense in $\mathbb{I}$.

Suppose that $\sigma$ is strongly erasing and verifies the optimality condition \ref{o.c}. Then, if $(w^{(n)})_{n\in\mathbb{N}_0}$ is any sequence of finite binary words, there is $x\in [w^{(0)}]$ and positive integers $h_1,h_2\dots$ (with $h_i$ depending only on $w^{(i)}$ for every positive integer $i$) such that $f_\sigma^{h_n}(x)\in [w^{(n)}]$ for every $n\in\mathbb{N}$. Moreover, exploiting point c) of Lemma \ref{lem_strongly}, we can write $\widetilde{x}$ as: $\widetilde{x}=\prod_{i=1}^\infty v^{(i)}$ where, for every positive integer $n$, $\sigma^{\epsilon\left({v^{(1)}\dots v^{(n-1)}}\right)}_{v^{(1)}\dots v^{(n-1)}}\left(v^{(n)}\right)$ has $w^{(n)}$ as a prefix.

\label{visitingcylinders}
\qed

If $\sigma$ is completely erasing and verifies the optimality condition \ref{o.c}, then for every $w,u\in\{0,1\}^*$ there is $s\in\mathbb{N}_0$ and $v\in\{0,1\}^*$ such that, setting $|w|=nk+m$ ($n\in\mathbb{N}_0\, , 0\le m<k$), $\sigma^{\epsilon(w)}(wv)=u\prod_{i=m+1}^{s}(w_\epsilon^\infty)_i$. Notice that by construction $\sigma_{w}(\prod_{i=m+1}^{s}(w_\epsilon^\infty)_i)=\epsilon$. 
\label{fillepsilon}
\qed

\noindent If $\sigma$ is completely erasing and verifies the optimality condition \ref{o.c}, then $f_\sigma$ is Li-Yorke chaotic, meaning that there exists an uncountable \textit{scrambled} subset of its domain, that is a set $S\subset \mathbb{I}$ such that, for every $x,y\in S$:
\begin{equation}
\liminf_{n\to\infty}|f_\sigma^n(x)-f_\sigma^n(y)|=0\quad ,\quad \limsup_{n\to\infty}|f_\sigma^n(x)-f_\sigma^n(y)|>0
\label{LYC}
\end{equation}
\label{LiYorke}

\noindent Consider a sequence $W=\{w^{(n)}\}_{n\in\mathbb{N}}$ of finite binary words such that $\{|w^{(n)}|\}_{n\in\mathbb{N}}$ is an unbounded sequence of positive integers. By Corollary \ref{visitingcylinders}, we can find $x\in\mathbb{I}$ such that its $f_\sigma$-orbit visits $[w^{(n)}]$ for every $n\in\mathbb{N}$,  and since $\sigma$ is completely erasing,  we can write $\widetilde{x}$ as: $\widetilde{x}=\prod_{i=1}^\infty v^{(i)}$ where, for every positive integer $n$ there is $q^{(n)}\in\{0,1\}^*$ such that 
\begin{equation}
\sigma^{\epsilon\left({v^{(1)}\dots v^{(n-1)}}\right)}_{v^{(1)}\dots v^{(n-1)}}\left( v^{(n)} \right)=w^{(n)}q^{(n)}.
\label{vvvvv}
\end{equation}
Moreover, by Corollary \ref{fillepsilon}, we can choose $q^{(n)}$ such that $\epsilon(w^{(n)}q^{(n)})=\epsilon(w^{(n)})$. 

\noindent Notice that \eqref{vvvvv} is the only property used to define $v^{(n)}$, which means that in fact we can define a family of points $X\subset\mathbb{I}$ as follows:
\begin{equation}
X=\{x=0.\prod_{n=1}^\infty v^{(n)}\ \text{where $v^{(n)}$ is such that \eqref{vvvvv} holds for every}\ n\in\mathbb{N}_0\}
\end{equation} 

\noindent In particular, by Lemma \ref{lem_completely}, we are free to choose $v^{(n)}$ so as to have that
\begin{equation}
\sigma^{\epsilon\left({v^{(1)}\dots v^{(n-1)}}\right)-1}_{v^{(1)}\dots v^{(n-1)}}\left( v^{(n)}\right) \text{has }u^{(n)} \text{ as a prefix},
\label{choice1}
\end{equation}
where $\sigma(u^{(n)})=w^{(n)}q^{(n)}$ and $u^{(n)}$ does not have $w_{\epsilon}$ as a $k$-factor (notice that we do not have to insert a suffix after $q^{(n)}$ because we know that Eq.\eqref{vvvvv} holds).

\noindent On the other hand, we can also make the choice
\begin{equation}
\sigma^{\epsilon\left({v^{(1)}\dots v^{(n-1)}}\right)-1}_{v^{(1)}\dots v^{(n-1)}}\left(v^{(n)}\right) \text{ has }w_{\epsilon}^2u^{(n)} \text{ as a prefix}.
\label{choice2}
\end{equation}
We underline that, for every $n\ge 1$, we can make choice $\eqref{choice1}$ or choice \eqref{choice2} while still retaining the property \eqref{vvvvv}. We want to use this to construct an uncountable scrambled subset of $\mathbb{I}$. For $\alpha=\alpha_{(1)}\alpha_{(2)}\dots \in\Omega$ (see Definition \ref{defiomegaxi}), let us define the set $X_{\alpha}\subset X$ of points in $\mathbb{I}$ such that, for every $x\in X_\alpha$,
\begin{equation}
\widetilde{x}=\prod_{n=1}^\infty v^{(n)}\ \text{where, for every $n$}:
\begin{cases}
\text{\eqref{choice1} holds if $\alpha_{(n)}=1$}\\
\text{\eqref{choice2} holds if $\alpha_{(n)}=0$}. 
\end{cases} 
\label{xxxxxx}
\end{equation}
Pick now exactly one point $x_\alpha$ from every set $X_\alpha$ and set $X_{\Omega}=\bigcup_{\alpha\in\Omega}\{x_{\alpha}\}$. 
We will show now that $X_\Omega$ is an uncountable scrambled set. Indeed, let $\alpha\ne\beta$ be two elements of $\Omega$. Since both $\widetilde{x_\alpha}$ and $\widetilde{x_\beta}$ verify \eqref{vvvvv} for every $n$, we have that $f_\sigma^n(x_\alpha),f_\sigma^n(x_\beta)\in [w^{(n)}]$. Since $|w^{(n)}|$ is unbounded, it follows that 
$$\liminf_{n\to\infty}|f_\sigma^n(x_\alpha)-f_\sigma^n(x_\beta)|=0.$$
Moreover, only for finitely many integers $n$ the word $u^{(n)}$ is shorter than 2$k$, so that $w_\epsilon$ is different from both $u^{(n)}_1\dots u^{(n)}_k$ and $u^{(n)}_{k+1}\dots u^{(n)}_{2k}$ for large enough $n$. It follows from Eqs. \eqref{choice2} and \eqref{xxxxxx} that, if $n$ is such that $\alpha_{(n)}\ne\beta_{(n)}$, then $q=\epsilon(v^{(1)}\dots v^{(n-1)})-1$ implies $|f^q_\sigma(x_\alpha)-f_\sigma^q(x_\beta)|> 2^{-2k}$. Since $\alpha$ and $\beta$ are not ultimately coinciding, it follows that $\limsup_{n\to\infty}|f_\sigma^n(x_\alpha)-f_\sigma^n(x_\beta)|>0$.
Finally, $X_\Omega$ is uncountable as $\alpha\ne\beta$ implies that $x_\alpha\ne x_\beta$ because by construction they have distinct $f_\sigma$-orbits.

Suppose that $\sigma$ is a completely erasing substitution verifying the optimality condition \ref{o.c}.  Then $f_\sigma$ has infinite topological entropy if, for every $w\in\{0,1\}^*$, 
\begin{equation}
\label{limepsilon}
\lim_{|w|\to\infty} \frac{|w|}{\epsilon(w)}=\infty.
\end{equation}
\label{entrop}

\noindent For every $w\in\{0,1\}^+$, set $F({\left| w \right|})=\max_{u\in\{0,1\}^{|w|}} \varepsilon(u) $. For $x_1,x_2 \in \mathbb{I}$ let us introduce the metric:
\begin{equation} \label{N_metric}
d_n(x_1,x_2) \coloneqq \max\{\left| f_\sigma^i(x_1)-f_\sigma^i(x_2)\right| : 0\le i \le n\}
\end{equation}
We say that a subset $S\subset \mathbb{I}$ is $(n,\varepsilon)$-separated in the metric $d_n$ if for all $x_1,x_2\in S$,  $x_1 \neq x_2$ we have that $d_N(x_1,x_2)\ge \varepsilon$ and we indicate by $\left| (n,\epsilon) \right|$ the maximum cardinality of an $(n,\varepsilon)$-separeted set.  We recall that the topological entropy $h$ of the map $f_\sigma$ can be written as (\cite{dinaburg1970correlation,bowen1971entropy}):
\begin{equation*}
h(f_\sigma)=\lim_{\varepsilon \to 0} \left( \limsup_{n \to \infty} \frac{1}{n} \log \left| (n,\varepsilon) \right| \right)
\end{equation*}

\noindent Fix now $\varepsilon=2^{-(k+1)}$. 
\begin{enumerate}
\item[\textit{Step 1.}] If $f_\sigma^t(x_1)\in [w_{(i)}\overline{w_\epsilon}]$ and $f_\sigma^t(x_2)\in [w_{(r)}\overline{w_\epsilon}]$,  for some $0\le t\le N$ ($i\neq r$), then $d_N(x_1,x_2)>\epsilon$. Indeed, we have the smallest possible difference between $f_\sigma^t(x_1)$ and $f_\sigma^t(x_2)$ when $w_{(i)}$ and $w_{(r)}$ differ at the $k$-th digit and $f_\sigma^t(x_1)=0.w_{(i)}\overline{w_\epsilon} 0^\infty\ ,\ f_\sigma^t(x_2)=0.w_{(r)}\overline{w_\epsilon} 1^\infty$ (or vice-versa), so that we have $\left|f_\sigma^t(x_1)-f_\sigma^t(x_2) \right|\ge\left| \frac{1}{2^k}-\frac{1}{2^{2k}} \right|\ge \frac{1}{2\cdot 2^k}=\epsilon$.


\noindent Set $t=F(k)$.

\item[\textit{Step 2.}]
For any $i,r\in \{1,\ldots, 2^k\}$, there exists $x\in [w_{(i)}\overline{w_\epsilon}]$ such that $f_\sigma^t(x)\in [w_{(r)}\overline{w_\epsilon} q^{(r)}]$ with $\sigma_{w_{(r)}\overline{w_\epsilon}}q^{(r)}=\epsilon$.

\noindent Indeed, let us fix $i,r\in \{1,\ldots, 2^k\}$.  Since by assumption $\epsilon(w) \le F(|w|)$ for every $w\in\{0,1\}^*$, we have $\epsilon(w_{(i)})=\epsilon(w_{(i)}\overline{w_{\epsilon}})\le t$.  By Lemma \ref{order_}, there exists a word $p\in \{0,1\}^*$ such that $\epsilon(p)=t-\epsilon(w_{(i)}\overline{w_\epsilon})$, and by Corollary \ref{fillepsilon}, there is $q\in\{0,1\}^*$ such that $\sigma^{\epsilon(w_{(i)}\overline{w_\epsilon})}(w_{(i)}\overline{w_\epsilon} q)=pp'$, with $p'\in\{0,1\}^*$ such that $\epsilon(pp')=\epsilon(p)$, and therefore $\epsilon(w_{(i)}\overline{w_\epsilon} q)=t$. Then the thesis follows by applying Lemma \ref{lem_strongly}, where $w=w_{(i)}\overline{w_\epsilon} q$, $u=w_{(r)}\overline{w_\epsilon}$ and $h=t$.

\item[\textit{Step 3.}] We will define now a family of sets $\{S^i \subset [w_{(i)}\overline{w_\epsilon}]\}_{i=1,\dots,2^k}$, each containing $2^{nk}$ ($n\in \mathbb{N}$) distinct points of $\mathbb{I}$, such that $\cup_{1\le i\le 2^k}S^i$ will be an $(n,\varepsilon)$-separated set.  We will indicate by $x_l^i$ ($l\in \{1,\ldots, 2^{nk}\}$) the points of $S^i$, where the subscript $l$ identifies their standard order as real numbers, and we will construct them iteratively, requesting properties which will be ensured by increasingly long prefixes of their binary expansion. By Step 2.,  for $i_1 \in\{1,\ldots, 2^k\}$ the points $x_l^{i_1}$ can be taken such that:
\begin{equation} \label{step_1}
f_\sigma^t(x_l^{i_1})\in S^{i_2} \quad \text{for } l\in \{(i_2-1)2^{(n-1)k}+1,\ldots, i_22^{(n-1)k}\}
\end{equation}
where $i_2\in \{1,\ldots, 2^k\}$.  Hence we can define the set 
$$S^{i_1i_2}=\{x:x\in S^{i_1}, f_\sigma^t(x)\in S^{i_2}\}$$
and we have $\left| S^{i_1i_2} \right|=2^{(n-1)k}$. Moreover, notice that after further $t$ iterates of $f_\sigma$, the prefix $w_{i_2}\overline{w_\epsilon}$ of every point $f_\sigma^t(x_l^{i_1})$ is mapped again in the empty word.  Therefore for every $i_1,i_2\in \{1,\ldots, 2^k\}$ and for $l\in \{(i_2-1)2^{(n-1)k}+1,\ldots, i_22^{(n-1)k}\} $,  Step 2. allows us to have:
\begin{equation} \label{step_2}
f_\sigma^{2t}(x_l^{i_1i_2})\in S^{i_3} \quad \text{for } l\in \{(i_3-1)2^{(n-2)k}+1,\ldots, i_32^{(n-2)k}\}
\end{equation}
where $\{x^{i_1i_2}_l \}_{l=1,\ldots, 2^{(n-1)k}}\in S^{i_1 i_2}$, the subscript $l$ indicates their standard order as reals and $i_3 \in \{1,\ldots,2^k \}$.  Hence we can define the set 
$$S^{i_1 i_2 i_3}=\{x:x\in S^{i_1}, f_\sigma^t(x)\in S^{i_2}, f_\sigma^{2t}(x)\in S^{i_3}\}$$ 
and we have $\left| S^{i_1 i_2 i_3} \right|=2^{(n-2)k}$. We can proceed in this way for further $n-3$ steps in order to obtain that 
\begin{equation} \label{step_t}
f_\sigma^{jt}(x_l^{i_1\ldots i_j})\in S^{i_{j+1}} \quad \text{for } l\in \{(i_{j+1}-1)2^{(n-j)k}+1,\ldots, i_{j+1}2^{(n-j)k}\}
\end{equation}
for all $j\in \{1,\ldots,n-1\}$,  where $\{x^{i_1\ldots i_j}_l\}_{l=1,\ldots, 2^k}\in S^{i_1 \ldots i_j}$, the subscript $l$ indicates their standard order as reals and $i_{j+1}\in \{1\ldots,2^k\}$.  We finally arrive at the set 
$$S^{i_1\ldots i_{j+1}}=(\{x: x\in S^{i_1}, f_\sigma^t(x)\in S^{i_2}, \ldots, f_\sigma^{jt}(x)\in S^{i_{j+1}}\})_{j\in \{1,\ldots,n-1\}}$$
such that $\left| S^{i_1\ldots i_{j+1}} \right|=2^k$.

\item[\textit{Step 4.}] Recalling Step 1., the last argument implies that $\bigcup_{i\in \{1,\ldots, 2^k\}} S^i$ is an $(nt,\epsilon)$-separated set, so that $\left|(nt,\varepsilon) \right| \ge 2^{(n+1)k}$. From this it follows that
\begin{equation}
h(f_\sigma)\ge \lim_{k\to +\infty}\limsup_{n\to\infty} \frac{\log 2^{(n+1)k}}{(n+1)t}=\lim_{k\to +\infty} \frac{k\log 2}{F(k)}
\end{equation}
which immediately implies the thesis.
\end{enumerate}

\noindent Take any $x\in\mathbb{I}$. For every closed neighborhood $K$ of $x$, there is $w\in\{0,1\}^*$ such that $\widetilde{x}=wv$ for some $v\in\{0,1\}^\omega$, and that $[w]\subset K$. If $\sigma$ is completely erasing and verifies the optimality condition, by Theorem \ref{mixing} we have $f_\sigma^{\epsilon(w)}([w])=\mathbb{I}$. Therefore, there exists $S^0\subset [w]$ such that $f_\sigma^{\epsilon(w)}(S^0)=\cup_{i} S^i$ (where $S^i$ are the same as in the previous proof). Then the same argument as above implies the following bounds:
\begin{equation}
h(f_\sigma, K)\ge h(f_\sigma, [w])\ge\lim_{k\to +\infty} \frac{k\log 2}{F(k)+\epsilon(w)}=\infty
\end{equation}
